import { createContext, useContext, useState, useEffect, ReactNode } from 'react';

type Theme = 'light' | 'dark' | 'system';
type ColorScheme = 'default' | 'high-contrast';

interface AppState {
  theme: Theme;
  colorScheme: ColorScheme;
  isOnline: boolean;
  lastSyncTime: number | null;
  isMenuOpen: boolean;
  isSidebarCollapsed: boolean;
  notifications: { id: string; message: string; type: 'info' | 'success' | 'error' | 'warning' }[];
}

interface AppStateContextType {
  state: AppState;
  setTheme: (theme: Theme) => void;
  setColorScheme: (scheme: ColorScheme) => void;
  toggleMenu: () => void;
  toggleSidebar: () => void;
  addNotification: (message: string, type: 'info' | 'success' | 'error' | 'warning') => void;
  removeNotification: (id: string) => void;
}

const defaultState: AppState = {
  theme: 'system',
  colorScheme: 'default',
  isOnline: true,
  lastSyncTime: null,
  isMenuOpen: false,
  isSidebarCollapsed: false,
  notifications: [],
};

const AppStateContext = createContext<AppStateContextType | undefined>(undefined);

// Create a BroadcastChannel for cross-tab state sync
const broadcastChannel = typeof window !== 'undefined' ? new BroadcastChannel('app-state') : null;

export function AppStateProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('app-state');
    return saved ? { ...defaultState, ...JSON.parse(saved) } : defaultState;
  });

  // Handle online/offline status
  useEffect(() => {
    const handleOnline = () => setState((prev) => ({ ...prev, isOnline: true }));
    const handleOffline = () => setState((prev) => ({ ...prev, isOnline: false }));

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Handle theme system preference changes
  useEffect(() => {
    if (state.theme === 'system') {
      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      const handleChange = (e: MediaQueryListEvent) => {
        document.documentElement.classList.toggle('dark', e.matches);
      };

      mediaQuery.addEventListener('change', handleChange);
      return () => mediaQuery.removeEventListener('change', handleChange);
    }
  }, [state.theme]);

  // Persist state changes to localStorage
  useEffect(() => {
    localStorage.setItem('app-state', JSON.stringify(state));
  }, [state]);

  // Handle cross-tab state sync
  useEffect(() => {
    if (!broadcastChannel) return;

    const handleMessage = (event: MessageEvent) => {
      if (event.data.type === 'STATE_UPDATE') {
        setState((prev) => ({ ...prev, ...event.data.payload }));
      }
    };

    broadcastChannel.addEventListener('message', handleMessage);
    return () => broadcastChannel.removeEventListener('message', handleMessage);
  }, []);

  // Apply theme and color scheme to document
  useEffect(() => {
    const root = document.documentElement;

    // Apply theme
    if (state.theme === 'system') {
      const isDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      root.classList.toggle('dark', isDark);
    } else {
      root.classList.toggle('dark', state.theme === 'dark');
    }

    // Apply color scheme
    root.classList.toggle('high-contrast', state.colorScheme === 'high-contrast');
  }, [state.theme, state.colorScheme]);

  const setTheme = (theme: Theme) => {
    setState((prev) => ({ ...prev, theme }));
    broadcastChannel?.postMessage({ type: 'STATE_UPDATE', payload: { theme } });
  };

  const setColorScheme = (colorScheme: ColorScheme) => {
    setState((prev) => ({ ...prev, colorScheme }));
    broadcastChannel?.postMessage({ type: 'STATE_UPDATE', payload: { colorScheme } });
  };

  const toggleMenu = () => {
    setState((prev) => ({ ...prev, isMenuOpen: !prev.isMenuOpen }));
  };

  const toggleSidebar = () => {
    setState((prev) => ({ ...prev, isSidebarCollapsed: !prev.isSidebarCollapsed }));
    broadcastChannel?.postMessage({
      type: 'STATE_UPDATE',
      payload: { isSidebarCollapsed: !state.isSidebarCollapsed },
    });
  };

  const addNotification = (message: string, type: 'info' | 'success' | 'error' | 'warning') => {
    try {
      const id = Date.now().toString();
      setState((prev) => ({
        ...prev,
        notifications: [...prev.notifications, { id, message, type }],
      }));

      // Auto-remove notifications after 5 seconds
      setTimeout(() => removeNotification(id), 5000);
    } catch (error) {
      console.error('Failed to add notification:', error);
    }
  };

  const removeNotification = (id: string) => {
    setState((prev) => ({
      ...prev,
      notifications: prev.notifications.filter((n) => n.id !== id),
    }));
  };

  return (
    <AppStateContext.Provider
      value={{
        state,
        setTheme,
        setColorScheme,
        toggleMenu,
        toggleSidebar,
        addNotification,
        removeNotification,
      }}
    >
      {children}
    </AppStateContext.Provider>
  );
}

export function useAppState() {
  const context = useContext(AppStateContext);
  if (!context) {
    throw new Error('useAppState must be used within an AppStateProvider');
  }
  return context;
}

// Optional: Export a hook for notifications only to prevent unnecessary re-renders
export function useNotifications() {
  const context = useContext(AppStateContext);
  if (!context) {
    throw new Error('useNotifications must be used within an AppStateProvider');
  }
  return {
    notifications: context.state.notifications,
    addNotification: context.addNotification,
    removeNotification: context.removeNotification,
  };
}

// Optional: Export hooks for specific state slices
export function useTheme() {
  const context = useContext(AppStateContext);
  if (!context) {
    throw new Error('useTheme must be used within an AppStateProvider');
  }
  return {
    theme: context.state.theme,
    colorScheme: context.state.colorScheme,
    setTheme: context.setTheme,
    setColorScheme: context.setColorScheme,
  };
}

import { useEffect, useState, useCallback, ReactNode, createContext, useContext } from 'react';

interface User {
  id: string;
  email: string;
  name: string;
  role: 'student' | 'teacher' | 'admin';
  preferences: {
    notifications: boolean;
    emailUpdates: boolean;
    language: string;
  };
}

interface AuthState {
  isAuthenticated: boolean;
  user: User | null;
  accessToken: string | null;
  refreshToken: string | null;
  loading: boolean;
  error: Error | null;
}

interface LoginCredentials {
  email: string;
  password: string;
}

interface RegisterData extends LoginCredentials {
  name: string;
  role?: 'student' | 'teacher';
}

interface AuthContextValue extends AuthState {
  login: (credentials: LoginCredentials) => Promise<void>;
  register: (data: RegisterData) => Promise<void>;
  logout: () => Promise<void>;
  updateUserPreferences: (preferences: Partial<User['preferences']>) => Promise<void>;
  resetPassword: (email: string) => Promise<void>;
  verifyEmail: (token: string) => Promise<void>;
}

const AuthContext = createContext<AuthContextValue | undefined>(undefined);

// Default auth state
const defaultAuthState: AuthState = {
  isAuthenticated: false,
  user: null,
  accessToken: null,
  refreshToken: null,
  loading: true,
  error: null,
};

// Time before access token expiry to trigger refresh (5 minutes)
const REFRESH_THRESHOLD = 5 * 60 * 1000;

export function AuthProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<AuthState>(() => {
    try {
      const saved = localStorage.getItem('auth-state');
      return saved ? { ...defaultAuthState, ...JSON.parse(saved) } : defaultAuthState;
    } catch {
      return defaultAuthState;
    }
  });

  const handleError = useCallback((error: unknown) => {
    const err = error instanceof Error ? error : new Error(String(error));
    console.error('Auth Error:', err);
    setState((prev) => ({ ...prev, error: err }));
  }, []);

  // Save auth state to localStorage
  useEffect(() => {
    try {
      if (state.isAuthenticated) {
        localStorage.setItem(
          'auth-state',
          JSON.stringify({
            isAuthenticated: state.isAuthenticated,
            user: state.user,
            accessToken: state.accessToken,
            refreshToken: state.refreshToken,
          })
        );
      } else {
        localStorage.removeItem('auth-state');
      }
    } catch (error) {
      console.error('Failed to save auth state:', error);
    }
  }, [state]);

  // Token refresh mechanism
  useEffect(() => {
    if (!state.accessToken || !state.refreshToken) return;

    try {
      const token = JSON.parse(atob(state.accessToken.split('.')[1]));
      const expiryTime = token.exp * 1000; // Convert to milliseconds
      const timeToExpiry = expiryTime - Date.now();

      if (timeToExpiry <= REFRESH_THRESHOLD) {
        refreshAccessToken();
      } else {
        // Schedule next refresh
        const refreshTimeout = setTimeout(refreshAccessToken, timeToExpiry - REFRESH_THRESHOLD);
        return () => clearTimeout(refreshTimeout);
      }
    } catch (error) {
      console.error('Failed to process token:', error);
    }
  }, [state.accessToken, state.refreshToken]);

  async function refreshAccessToken() {
    try {
      if (!state.refreshToken) throw new Error('No refresh token available');

      const response = await fetch('/api/auth/refresh', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ refreshToken: state.refreshToken }),
      });

      if (!response.ok) throw new Error('Failed to refresh token');

      const data = await response.json();
      setState((prev) => ({
        ...prev,
        accessToken: data.accessToken,
      }));
    } catch (error) {
      handleAuthError(error);
      // Force logout on refresh failure
      await logout();
    }
  }

  function handleAuthError(error: unknown) {
    const err = error instanceof Error ? error : new Error(String(error));
    setState((prev) => ({ ...prev, error: err }));
    console.error('Auth Error:', err);
  }

  async function login({ email, password }: LoginCredentials) {
    try {
      setState((prev) => ({ ...prev, loading: true, error: null }));

      const response = await fetch('/api/auth/login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ email, password }),
      });

      if (!response.ok) throw new Error('Invalid credentials');

      const { user, accessToken, refreshToken } = await response.json();

      setState((prev) => ({
        ...prev,
        isAuthenticated: true,
        user,
        accessToken,
        refreshToken,
        loading: false,
        error: null,
      }));
    } catch (error) {
      handleAuthError(error);
    } finally {
      setState((prev) => ({ ...prev, loading: false }));
    }
  }

  async function register(data: RegisterData) {
    try {
      setState((prev) => ({ ...prev, loading: true, error: null }));

      const response = await fetch('/api/auth/register', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(data),
      });

      if (!response.ok) throw new Error('Registration failed');
    } catch (error) {
      handleAuthError(error);
    } finally {
      setState((prev) => ({ ...prev, loading: false }));
    }
  }

  async function logout() {
    try {
      if (state.refreshToken) {
        await fetch('/api/auth/logout', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({ refreshToken: state.refreshToken }),
        });
      }
    } catch (error) {
      console.error('Logout error:', error);
    } finally {
      setState(defaultAuthState);
      localStorage.removeItem('auth-state');
    }
  }

  async function updateUserPreferences(preferences: Partial<User['preferences']>) {
    try {
      if (!state.user || !state.accessToken) throw new Error('Not authenticated');

      const response = await fetch('/api/users/preferences', {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${state.accessToken}`,
        },
        body: JSON.stringify({ preferences }),
      });

      if (!response.ok) throw new Error('Failed to update preferences');

      const updatedUser = await response.json();
      setState((prev) => ({
        ...prev,
        user: updatedUser,
      }));
    } catch (error) {
      handleAuthError(error);
    }
  }

  async function resetPassword(email: string) {
    try {
      setState((prev) => ({ ...prev, loading: true, error: null }));

      const response = await fetch('/api/auth/reset-password', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ email }),
      });

      if (!response.ok) throw new Error('Failed to initiate password reset');
    } catch (error) {
      handleAuthError(error);
    } finally {
      setState((prev) => ({ ...prev, loading: false }));
    }
  }

  async function verifyEmail(token: string) {
    try {
      setState((prev) => ({ ...prev, loading: true, error: null }));

      const response = await fetch('/api/auth/verify-email', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ token }),
      });

      if (!response.ok) throw new Error('Failed to verify email');
    } catch (error) {
      handleAuthError(error);
    } finally {
      setState((prev) => ({ ...prev, loading: false }));
    }
  }

  return (
    <AuthContext.Provider
      value={{
        ...state,
        login,
        register,
        logout,
        updateUserPreferences,
        resetPassword,
        verifyEmail,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

// Hook to access the entire auth state and methods
export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

// Specialized hooks for specific auth state properties
export function useAuthStatus() {
  const context = useAuth();
  return {
    isAuthenticated: context.isAuthenticated,
    loading: context.loading,
  };
}

export function useUser() {
  const context = useAuth();
  return context.user;
}

// Higher-order component for protected routes
export function withAuth<P extends object>(
  WrappedComponent: React.ComponentType<P>,
  requiredRole?: User['role']
) {
  return function WithAuthComponent(props: P) {
    const { isAuthenticated, user, loading } = useAuth();

    if (loading) {
      return <div>Loading...</div>;
    }

    if (!isAuthenticated) {
      // Redirect to login page
      window.location.href = '/login';
      return null;
    }

    if (requiredRole && user?.role !== requiredRole) {
      // Redirect to unauthorized page
      window.location.href = '/unauthorized';
      return null;
    }

    return <WrappedComponent {...props} />;
  };
}

import { createContext, useContext, useState, ReactNode } from 'react';

type BookmarksContextType = {
  bookmarks: string[];
  toggleBookmark: (lessonId: string) => void;
  isBookmarked: (lessonId: string) => boolean;
};

const BookmarksContext = createContext<BookmarksContextType | undefined>(undefined);

export function BookmarksProvider({ children }: { children: ReactNode }) {
  const [bookmarks, setBookmarks] = useState<string[]>(() => {
    const saved = localStorage.getItem('bookmarked-lessons');
    return saved ? JSON.parse(saved) : [];
  });

  function toggleBookmark(lessonId: string) {
    setBookmarks((prev) => {
      const updated = prev.includes(lessonId)
        ? prev.filter((id) => id !== lessonId)
        : [...prev, lessonId];
      localStorage.setItem('bookmarked-lessons', JSON.stringify(updated));
      return updated;
    });
  }

  function isBookmarked(lessonId: string) {
    return bookmarks.includes(lessonId);
  }

  return (
    <BookmarksContext.Provider value={{ bookmarks, toggleBookmark, isBookmarked }}>
      {children}
    </BookmarksContext.Provider>
  );
}

export function useBookmarks() {
  const context = useContext(BookmarksContext);
  if (!context) throw new Error('useBookmarks must be used within a BookmarksProvider');
  return context;
}

import {
  createContext,
  useContext,
  useState,
  useCallback,
  ReactNode,
  Component,
  ErrorInfo,
} from 'react';

interface ErrorState {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

interface ErrorContextType {
  errors: Record<string, ErrorState>;
  addError: (contextName: string, error: Error, errorInfo?: ErrorInfo) => void;
  clearError: (contextName: string) => void;
  clearAllErrors: () => void;
}

const ErrorContext = createContext<ErrorContextType | undefined>(undefined);

interface Props {
  children: ReactNode;
  fallback?: React.ComponentType<{ error: Error; resetError: () => void }>;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

// Error Boundary Component
export class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    // Log the error to an error reporting service
    this.props.onError?.(error, errorInfo);
  }

  resetError = () => {
    this.setState({ hasError: false, error: null });
  };

  render() {
    const { fallback: Fallback, children } = this.props;

    if (this.state.hasError && this.state.error) {
      if (Fallback) {
        return <Fallback error={this.state.error} resetError={this.resetError} />;
      }

      return (
        <div role="alert" className="p-4 bg-red-50 border border-red-200 rounded-lg">
          <h2 className="text-lg font-semibold text-red-800">Something went wrong</h2>
          <p className="mt-2 text-sm text-red-700">{this.state.error.message}</p>
          <button
            onClick={this.resetError}
            className="mt-4 px-4 py-2 text-sm font-medium text-white bg-red-600 rounded-md hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500"
          >
            Try again
          </button>
        </div>
      );
    }

    return children;
  }
}

// Context Provider for Global Error Handling
export function ErrorProvider({ children }: { children: ReactNode }) {
  const [errors, setErrors] = useState<Record<string, ErrorState>>({});

  const addError = useCallback((contextName: string, error: Error, errorInfo?: ErrorInfo) => {
    setErrors((prev) => ({
      ...prev,
      [contextName]: {
        hasError: true,
        error,
        errorInfo: errorInfo || null,
      },
    }));

    // Log error to console in development
    if (process.env.NODE_ENV === 'development') {
      console.error(`Error in ${contextName}:`, error);
      if (errorInfo) {
        console.error('Error Info:', errorInfo);
      }
    }

    // Here you could add error reporting service integration
    // e.g., Sentry, LogRocket, etc.
  }, []);

  const clearError = useCallback((contextName: string) => {
    setErrors((prev) => {
      const newErrors = { ...prev };
      delete newErrors[contextName];
      return newErrors;
    });
  }, []);

  const clearAllErrors = useCallback(() => {
    setErrors({});
  }, []);

  return (
    <ErrorContext.Provider
      value={{
        errors,
        addError,
        clearError,
        clearAllErrors,
      }}
    >
      {children}
    </ErrorContext.Provider>
  );
}

export function useError() {
  const context = useContext(ErrorContext);
  if (!context) {
    throw new Error('useError must be used within an ErrorProvider');
  }
  return context;
}

// Higher Order Component to wrap context providers with error handling
export function withErrorHandling<P extends object>(
  WrappedComponent: React.ComponentType<P>,
  contextName: string
) {
  return function WithErrorHandlingComponent(props: P) {
    const { addError } = useError();

    return (
      <ErrorBoundary onError={(error, errorInfo) => addError(contextName, error, errorInfo)}>
        <WrappedComponent {...props} />
      </ErrorBoundary>
    );
  };
}

// Custom hook for try-catch error handling in contexts
export function useErrorHandler(contextName: string) {
  const { addError } = useError();

  return useCallback(
    async <T,>(promise: Promise<T>) => {
      try {
        return await promise;
      } catch (error) {
        addError(contextName, error instanceof Error ? error : new Error(String(error)));
        throw error;
      }
    },
    [addError, contextName]
  );
}

import { createContext, useContext, useState, ReactNode, useEffect, useCallback } from 'react';
import { createTranslator, type SupportedLanguage } from '../i18n';

type Language = SupportedLanguage;

interface LanguageContextType {
  language: Language;
  toggleLanguage: () => void;
  t: (key: string) => string;
  error: Error | null;
}

// All translations are now externalized under client/src/i18n

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

export function BaseLanguageProvider({ children }: { children: ReactNode }) {
  const [language, setLanguage] = useState<Language>(() => {
    try {
      const saved = localStorage.getItem('education-for-democracy-language');
      return (saved as Language) || 'en';
    } catch (error) {
      console.error('Failed to load language preference:', error);
      return 'en';
    }
  });

  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    try {
      localStorage.setItem('education-for-democracy-language', language);
    } catch (error) {
      const err = error instanceof Error ? error : new Error('Failed to save language preference');
      setError(err);
      console.error('Language Context Error:', err);
    }
  }, [language]);

  const toggleLanguage = () => {
    try {
      setLanguage((prev) => (prev === 'en' ? 'ne' : 'en'));
      setError(null);
    } catch (error) {
      const err = error instanceof Error ? error : new Error('Failed to toggle language');
      setError(err);
      console.error('Language Context Error:', err);
    }
  };

  const [translator, setTranslator] = useState<((key: string) => string) | null>(null);

  useEffect(() => {
    let active = true;
    createTranslator(language, { fallback: 'en' })
      .then((tfn) => {
        if (active) setTranslator(() => tfn);
      })
      .catch((err) => {
        setError(err instanceof Error ? err : new Error('Failed to load translations'));
      });
    return () => {
      active = false;
    };
  }, [language]);

  const t = useCallback(
    (key: string) => {
      if (!translator) return key; // loading state
      return translator(key);
    },
    [translator]
  );

  return (
    <LanguageContext.Provider value={{ language, toggleLanguage, t, error }}>
      {children}
    </LanguageContext.Provider>
  );
}

// Export the base provider directly
export const LanguageProvider = BaseLanguageProvider;

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (context === undefined) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
}

import { useCallback, useState, useEffect, ReactNode, createContext, useContext } from 'react';
import type {
  Course,
  Module,
  Lesson,
  Assessment,
  LearningPath,
  LearningProfile,
  ContentProgress,
  AssessmentResult,
  CompletionStatus,
  ContentType,
  DifficultyLevel,
} from '../types/learning';

interface LearningState {
  courses: Course[];
  learningPaths: LearningPath[];
  currentCourse?: Course;
  currentModule?: Module;
  currentLesson?: Lesson;
  userProfile?: LearningProfile;
  loading: boolean;
  error: Error | null;
}

interface LearningContextValue extends LearningState {
  // Content Management
  loadCourse: (courseId: string) => Promise<Course>;
  loadModule: (moduleId: string) => Promise<Module>;
  loadLesson: (lessonId: string) => Promise<Lesson>;

  // Progress Tracking
  updateProgress: (
    contentId: string,
    status: CompletionStatus,
    data?: Partial<ContentProgress>
  ) => Promise<void>;
  submitAssessment: (
    assessmentId: string,
    answers: Record<string, string | string[]>
  ) => Promise<AssessmentResult>;

  // Learning Paths
  enrollInPath: (pathId: string) => Promise<void>;
  switchPath: (pathId: string) => Promise<void>;
  getNextContent: () => Promise<{ type: ContentType; id: string } | null>;

  // User Profile
  updatePreferences: (preferences: Partial<LearningProfile['preferences']>) => Promise<void>;

  // Analytics
  getRecommendations: () => Promise<Course[]>;
  getProgress: (courseId?: string) => Promise<ContentProgress[]>;
  getStatistics: () => Promise<LearningProfile['statistics']>;
}

const LearningContext = createContext<LearningContextValue | undefined>(undefined);

const initialState: LearningState = {
  courses: [],
  learningPaths: [],
  loading: false,
  error: null,
};

interface LearningProviderProps {
  children: ReactNode;
  userId?: string;
}

export function LearningProvider({ children, userId }: LearningProviderProps) {
  const [error, setError] = useState<Error | null>(null);

  // Utility function for API calls with error handling
  const apiCall = useCallback(
    async <T,>(endpoint: string, options: RequestInit = {}): Promise<T> => {
      try {
        const response = await fetch(`/api/learning/${endpoint}`, {
          ...options,
          headers: {
            'Content-Type': 'application/json',
            ...options.headers,
          },
        });

        if (!response.ok) {
          throw new Error(`API call failed: ${response.statusText}`);
        }

        return response.json();
      } catch (error) {
        const err = error instanceof Error ? error : new Error(String(error));
        setError(err);
        console.error('Learning Context Error:', err);
        throw err;
      }
    },
    []
  );

  // Content Management Methods
  const loadCourse = useCallback(
    async (courseId: string): Promise<Course> => {
      return apiCall<Course>(`courses/${courseId}`);
    },
    [apiCall]
  );

  const loadModule = useCallback(
    async (moduleId: string): Promise<Module> => {
      return apiCall<Module>(`modules/${moduleId}`);
    },
    [apiCall]
  );

  const loadLesson = useCallback(
    async (lessonId: string): Promise<Lesson> => {
      return apiCall<Lesson>(`lessons/${lessonId}`);
    },
    [apiCall]
  );

  // Progress Tracking Methods
  const updateProgress = useCallback(
    async (
      contentId: string,
      status: CompletionStatus,
      data?: Partial<ContentProgress>
    ): Promise<void> => {
      if (!userId) throw new Error('User must be authenticated');

      await apiCall('progress', {
        method: 'POST',
        body: JSON.stringify({
          contentId,
          status,
          ...data,
          userId,
        }),
      });
    },
    [apiCall, userId]
  );

  const submitAssessment = useCallback(
    async (
      assessmentId: string,
      answers: Record<string, string | string[]>
    ): Promise<AssessmentResult> => {
      if (!userId) throw new Error('User must be authenticated');

      const result = await apiCall<AssessmentResult>('assessment/submit', {
        method: 'POST',
        body: JSON.stringify({
          assessmentId,
          answers,
          userId,
        }),
      });

      return result;
    },
    [apiCall, userId]
  );

  // Learning Path Methods
  const enrollInPath = useCallback(
    async (pathId: string): Promise<void> => {
      if (!userId) throw new Error('User must be authenticated');

      await apiCall('paths/enroll', {
        method: 'POST',
        body: JSON.stringify({
          pathId,
          userId,
        }),
      });
    },
    [apiCall, userId]
  );

  const switchPath = useCallback(
    async (pathId: string): Promise<void> => {
      if (!userId) throw new Error('User must be authenticated');

      await apiCall('paths/switch', {
        method: 'POST',
        body: JSON.stringify({
          pathId,
          userId,
        }),
      });
    },
    [apiCall, userId]
  );

  const getNextContent = useCallback(async (): Promise<{
    type: ContentType;
    id: string;
  } | null> => {
    if (!userId) throw new Error('User must be authenticated');

    return apiCall('content/next', {
      method: 'GET',
    });
  }, [apiCall, userId]);

  // User Profile Methods
  const updatePreferences = useCallback(
    async (preferences: Partial<LearningProfile['preferences']>): Promise<void> => {
      if (!userId) throw new Error('User must be authenticated');

      await apiCall('profile/preferences', {
        method: 'PATCH',
        body: JSON.stringify(preferences),
      });
    },
    [apiCall, userId]
  );

  // Analytics Methods
  const getRecommendations = useCallback(async (): Promise<Course[]> => {
    if (!userId) throw new Error('User must be authenticated');

    return apiCall('recommendations');
  }, [apiCall, userId]);

  const getProgress = useCallback(
    async (courseId?: string): Promise<ContentProgress[]> => {
      if (!userId) throw new Error('User must be authenticated');

      return apiCall('progress', {
        method: 'GET',
        ...(courseId ? { params: { courseId } } : {}),
      });
    },
    [apiCall, userId]
  );

  const getStatistics = useCallback(async (): Promise<LearningProfile['statistics']> => {
    if (!userId) throw new Error('User must be authenticated');

    return apiCall('statistics');
  }, [apiCall, userId]);

  const value: LearningContextValue = {
    ...initialState,
    error,
    loadCourse,
    loadModule,
    loadLesson,
    updateProgress,
    submitAssessment,
    enrollInPath,
    switchPath,
    getNextContent,
    updatePreferences,
    getRecommendations,
    getProgress,
    getStatistics,
  };

  return <LearningContext.Provider value={value}>{children}</LearningContext.Provider>;
}

// Hook to access the entire learning context
export function useLearning() {
  const context = useContext(LearningContext);
  if (context === undefined) {
    throw new Error('useLearning must be used within a LearningProvider');
  }
  return context;
}

// Specialized hooks for specific learning state
export function useCurrentCourse() {
  const context = useLearning();
  return context.currentCourse;
}

export function useCurrentLesson() {
  const context = useLearning();
  return context.currentLesson;
}

export function useLearningProgress() {
  const context = useLearning();
  return {
    updateProgress: context.updateProgress,
    getProgress: context.getProgress,
    getStatistics: context.getStatistics,
  };
}

export function useLearningPath() {
  const context = useLearning();
  return {
    enrollInPath: context.enrollInPath,
    switchPath: context.switchPath,
    getNextContent: context.getNextContent,
  };
}

// Custom hooks for specific features
export function useAssessment() {
  const { submitAssessment } = useLearning();
  const [currentAssessment, setCurrentAssessment] = useState<Assessment | null>(null);

  const startAssessment = useCallback(async (assessmentId: string) => {
    try {
      // Load assessment details
      const response = await fetch(`/api/learning/assessment/${assessmentId}`);
      if (!response.ok) {
        throw new Error(`Failed to load assessment: ${response.statusText}`);
      }
      const assessment = await response.json();
      setCurrentAssessment(assessment);
    } catch (error) {
      console.error('Assessment loading error:', error);
      throw error;
    }
  }, []);

  return {
    currentAssessment,
    startAssessment,
    submitAssessment,
  };
}

export function useRecommendations() {
  const { getRecommendations } = useLearning();
  const [recommendations, setRecommendations] = useState<Course[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const loadRecommendations = async () => {
      setLoading(true);
      try {
        const courses = await getRecommendations();
        setRecommendations(courses);
      } catch (error) {
        console.error('Failed to load recommendations:', error);
      } finally {
        setLoading(false);
      }
    };

    loadRecommendations();
  }, [getRecommendations]);

  return { recommendations, loading };
}

