import { createContext, useContext, useState, ReactNode, useEffect, useCallback } from 'react';
import { achievements, Achievement } from '@shared/achievements';
import { useOfflineSupport } from '../hooks/use-offline-support';
import { progressAPI } from '@/lib/progressApi';

interface ProgressData {
  totalPoints: number;
  completedLessons: string[];
  completedSections: Record<string, string[]>; // lessonId -> sectionIds[]
  quizScores: Record<string, number>;
  unlockedAchievements: string[];
  perfectQuizzes: string[]; // quizIds with 100% score
  lastLessonCompletionTime?: number; // timestamp for dedication achievements
}

interface ProgressContextType {
  progress: ProgressData;
  addPoints: (points: number) => void;
  markLessonComplete: (lessonId: string) => Promise<void>;
  markSectionComplete: (lessonId: string, sectionId: string) => void;
  isSectionComplete: (lessonId: string, sectionId: string) => boolean;
  isLessonComplete: (lessonId: string) => boolean;
  recordQuizScore: (quizId: string, score: number) => Promise<void>;
  resetProgress: () => void;
  getUnlockedAchievements: () => Achievement[];
  getLockedAchievements: () => Achievement[];
  checkForNewAchievements: () => Achievement[];
  getTotalSectionsCompleted: () => number;
  onAchievementUnlocked?: (achievement: Achievement) => void;
}

const defaultProgress: ProgressData = {
  totalPoints: 0,
  completedLessons: [],
  completedSections: {},
  quizScores: {},
  unlockedAchievements: [],
  perfectQuizzes: [],
};

const ProgressContext = createContext<ProgressContextType | undefined>(undefined);

interface ProgressProviderProps {
  children: ReactNode;
  onAchievementUnlocked?: (achievement: Achievement) => void;
}

export function ProgressProvider({ children, onAchievementUnlocked }: ProgressProviderProps) {
  const { isOnline, saveOfflineProgress, syncOfflineProgress } = useOfflineSupport();

  const [progress, setProgress] = useState<ProgressData>(() => {
    const saved = localStorage.getItem('education-for-democracy-progress');
    if (saved) {
      const parsedProgress = JSON.parse(saved);
      // Migrate old progress data to include new fields
      return {
        ...defaultProgress,
        ...parsedProgress,
        unlockedAchievements: parsedProgress.unlockedAchievements || [],
        perfectQuizzes: parsedProgress.perfectQuizzes || [],
      };
    }
    return defaultProgress;
  });

  // Sync with localStorage and handle offline storage
  useEffect(() => {
    // Always save to localStorage
    localStorage.setItem('education-for-democracy-progress', JSON.stringify(progress));

    // If offline, save to IndexedDB for later sync
    if (!isOnline) {
      saveOfflineProgress(progress);
    }
  }, [progress, isOnline, saveOfflineProgress]);

  // Try to sync when we come back online
  useEffect(() => {
    if (isOnline) {
      syncOfflineProgress();
    }
  }, [isOnline, syncOfflineProgress]);

  const addPoints = (points: number) => {
    setProgress((prev) => ({
      ...prev,
      totalPoints: prev.totalPoints + points,
    }));
  };

  const markLessonComplete = async (lessonId: string) => {
    const now = Date.now();
    setProgress((prev) => ({
      ...prev,
      completedLessons: prev.completedLessons.includes(lessonId)
        ? prev.completedLessons
        : [...prev.completedLessons, lessonId],
      lastLessonCompletionTime: now,
    }));

    // Sync with API
    try {
      if (isOnline) {
        await progressAPI.markLessonComplete({
          lessonId,
          userId: progressAPI.getUserId(),
          completed: true,
        });
        console.log('Lesson completion synced with API:', lessonId);
      }
    } catch (error) {
      console.error('Failed to sync lesson completion with API:', error);
      // Continue with local storage - offline support will handle sync later
    }
  };

  const recordQuizScore = async (quizId: string, score: number) => {
    setProgress((prev) => {
      const newPerfectQuizzes =
        score === 100 && !prev.perfectQuizzes.includes(quizId)
          ? [...prev.perfectQuizzes, quizId]
          : prev.perfectQuizzes;

      return {
        ...prev,
        quizScores: {
          ...prev.quizScores,
          [quizId]: score,
        },
        perfectQuizzes: newPerfectQuizzes,
      };
    });

    // Sync with API
    try {
      if (isOnline) {
        // Assuming a standard quiz has 10 questions and we calculate correctAnswers from score
        const totalQuestions = 10; // Default, should be passed as parameter in real implementation
        const correctAnswers = Math.round((score / 100) * totalQuestions);

        await progressAPI.recordQuizResult({
          quizId,
          userId: progressAPI.getUserId(),
          score,
          totalQuestions,
          correctAnswers,
        });
        console.log('Quiz result synced with API:', { quizId, score });
      }
    } catch (error) {
      console.error('Failed to sync quiz result with API:', error);
      // Continue with local storage - offline support will handle sync later
    }
  };

  const markSectionComplete = (lessonId: string, sectionId: string) => {
    setProgress((prev) => {
      const lessonSections = prev.completedSections[lessonId] || [];
      const newSections = lessonSections.includes(sectionId)
        ? lessonSections
        : [...lessonSections, sectionId];

      return {
        ...prev,
        completedSections: {
          ...prev.completedSections,
          [lessonId]: newSections,
        },
      };
    });
  };

  const isSectionComplete = (lessonId: string, sectionId: string) => {
    const lessonSections = progress.completedSections[lessonId] || [];
    return lessonSections.includes(sectionId);
  };

  const isLessonComplete = (lessonId: string) => {
    return progress.completedLessons.includes(lessonId);
  };

  const checkAchievementUnlocked = useCallback(
    (achievement: Achievement, currentProgress: ProgressData): boolean => {
      const { requirement } = achievement;

      switch (requirement.type) {
        case 'lessons_completed':
          if (requirement.lessonId) {
            return currentProgress.completedLessons.includes(requirement.lessonId);
          }

          // Check for time-based dedication achievements
          if (achievement.id === 'early_bird' && currentProgress.lastLessonCompletionTime) {
            const completionDate = new Date(currentProgress.lastLessonCompletionTime);
            const hour = completionDate.getHours();
            return (
              currentProgress.completedLessons.length >= requirement.value && hour >= 6 && hour < 11
            );
          }

          if (achievement.id === 'night_owl' && currentProgress.lastLessonCompletionTime) {
            const completionDate = new Date(currentProgress.lastLessonCompletionTime);
            const hour = completionDate.getHours();
            return (
              currentProgress.completedLessons.length >= requirement.value &&
              hour >= 18 &&
              hour < 23
            );
          }

          return currentProgress.completedLessons.length >= requirement.value;

        case 'sections_completed':
          const totalSections = Object.values(currentProgress.completedSections).reduce(
            (sum, sections) => sum + sections.length,
            0
          );
          return totalSections >= requirement.value;

        case 'quiz_score':
          return Object.values(currentProgress.quizScores).some(
            (score) => score >= requirement.value
          );

        case 'points_earned':
          return currentProgress.totalPoints >= requirement.value;

        case 'perfect_quizzes':
          return currentProgress.perfectQuizzes.length >= requirement.value;

        default:
          return false;
      }
    },
    []
  );

  const checkForNewAchievements = useCallback((): Achievement[] => {
    const newAchievements: Achievement[] = [];

    // Ensure unlockedAchievements exists
    const unlockedAchievements = progress.unlockedAchievements || [];

    for (const achievement of achievements) {
      if (
        !unlockedAchievements.includes(achievement.id) &&
        checkAchievementUnlocked(achievement, progress)
      ) {
        newAchievements.push(achievement);
      }
    }

    if (newAchievements.length > 0) {
      setProgress((prev) => ({
        ...prev,
        unlockedAchievements: [
          ...(prev.unlockedAchievements || []),
          ...newAchievements.map((a) => a.id),
        ],
        totalPoints:
          prev.totalPoints +
          newAchievements.reduce((sum, achievement) => sum + achievement.points, 0),
      }));

      // Notify about new achievements
      newAchievements.forEach((achievement) => {
        if (onAchievementUnlocked) {
          onAchievementUnlocked(achievement);
        }
      });
    }

    return newAchievements;
  }, [progress, checkAchievementUnlocked, onAchievementUnlocked]);

  const getUnlockedAchievements = useCallback((): Achievement[] => {
    const unlockedAchievements = progress.unlockedAchievements || [];
    return achievements.filter((achievement) => unlockedAchievements.includes(achievement.id));
  }, [progress.unlockedAchievements]);

  const getLockedAchievements = useCallback((): Achievement[] => {
    const unlockedAchievements = progress.unlockedAchievements || [];
    return achievements.filter((achievement) => !unlockedAchievements.includes(achievement.id));
  }, [progress.unlockedAchievements]);

  const getTotalSectionsCompleted = useCallback((): number => {
    return Object.values(progress.completedSections).reduce(
      (sum, sections) => sum + sections.length,
      0
    );
  }, [progress.completedSections]);

  // Check for achievements when progress changes
  useEffect(() => {
    checkForNewAchievements();
  }, [
    progress.completedLessons,
    progress.totalPoints,
    progress.quizScores,
    progress.perfectQuizzes,
    progress.lastLessonCompletionTime,
    checkForNewAchievements,
  ]);

  const resetProgress = () => {
    setProgress(defaultProgress);
  };

  return (
    <ProgressContext.Provider
      value={{
        progress,
        addPoints,
        markLessonComplete,
        markSectionComplete,
        isSectionComplete,
        isLessonComplete,
        recordQuizScore,
        resetProgress,
        getUnlockedAchievements,
        getLockedAchievements,
        checkForNewAchievements,
        getTotalSectionsCompleted,
        onAchievementUnlocked,
      }}
    >
      {children}
    </ProgressContext.Provider>
  );
}

export function useProgress() {
  const context = useContext(ProgressContext);
  if (context === undefined) {
    throw new Error('useProgress must be used within a ProgressProvider');
  }
  return context;
}

import {
  useEffect,
  useState,
  ReactNode,
  useRef,
  useCallback,
  createContext,
  useContext,
} from 'react';

export type Breakpoint = 'xs' | 'sm' | 'md' | 'lg' | 'xl' | '2xl';
export type Orientation = 'portrait' | 'landscape';
export type DeviceType = 'mobile' | 'tablet' | 'desktop';

interface ViewportState {
  width: number;
  height: number;
  breakpoint: Breakpoint;
  orientation: Orientation;
  deviceType: DeviceType;
  isLandscape: boolean;
  isPortrait: boolean;
  isMobile: boolean;
  isTablet: boolean;
  isDesktop: boolean;
  isPwa: boolean;
  isStandalone: boolean;
}

const breakpoints = {
  xs: 0,
  sm: 640,
  md: 768,
  lg: 1024,
  xl: 1280,
  '2xl': 1536,
};

function getBreakpoint(width: number): Breakpoint {
  if (width >= breakpoints['2xl']) return '2xl';
  if (width >= breakpoints.xl) return 'xl';
  if (width >= breakpoints.lg) return 'lg';
  if (width >= breakpoints.md) return 'md';
  if (width >= breakpoints.sm) return 'sm';
  return 'xs';
}

function getDeviceType(width: number): DeviceType {
  if (width >= breakpoints.lg) return 'desktop';
  if (width >= breakpoints.md) return 'tablet';
  return 'mobile';
}

const ViewportContext = createContext<ViewportState | undefined>(undefined);

export function ViewportProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<ViewportState>(() => {
    const width = typeof window !== 'undefined' ? window.innerWidth : 0;
    const height = typeof window !== 'undefined' ? window.innerHeight : 0;
    const orientation = height > width ? 'portrait' : 'landscape';

    return {
      width,
      height,
      breakpoint: getBreakpoint(width),
      orientation,
      deviceType: getDeviceType(width),
      isLandscape: orientation === 'landscape',
      isPortrait: orientation === 'portrait',
      isMobile: width < breakpoints.md,
      isTablet: width >= breakpoints.md && width < breakpoints.lg,
      isDesktop: width >= breakpoints.lg,
      isPwa: window.matchMedia('(display-mode: standalone)').matches,
      // Non-standard iOS Safari property access via casting
      isStandalone:
        (window.navigator as any).standalone ||
        window.matchMedia('(display-mode: standalone)').matches,
    };
  });

  // Simple debounce implementation to avoid excessive re-renders
  const timeoutRef = useRef<ReturnType<typeof setTimeout>>();
  const debouncedSetState = useCallback((updates: Partial<ViewportState>) => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }
    timeoutRef.current = setTimeout(() => {
      setState((prev) => ({ ...prev, ...updates }));
    }, 150);
  }, []);

  useEffect(() => {
    function handleResize() {
      const width = window.innerWidth;
      const height = window.innerHeight;
      const orientation = height > width ? 'portrait' : 'landscape';
      const breakpoint = getBreakpoint(width);
      const deviceType = getDeviceType(width);

      debouncedSetState({
        width,
        height,
        breakpoint,
        orientation,
        deviceType,
        isLandscape: orientation === 'landscape',
        isPortrait: orientation === 'portrait',
        isMobile: width < breakpoints.md,
        isTablet: width >= breakpoints.md && width < breakpoints.lg,
        isDesktop: width >= breakpoints.lg,
      });
    }

    // Listen for resize and orientation change events
    window.addEventListener('resize', handleResize);
    window.addEventListener('orientationchange', handleResize);

    // Initial check
    handleResize();

    // Cleanup
    return () => {
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('orientationchange', handleResize);
    };
  }, [debouncedSetState]);

  // Update PWA status when display mode changes
  useEffect(() => {
    const mediaQuery = window.matchMedia('(display-mode: standalone)');

    function handleDisplayModeChange(e: MediaQueryListEvent) {
      setState((prev) => ({
        ...prev,
        isPwa: e.matches,
        // Non-standard iOS Safari property access via casting
        isStandalone: e.matches || (window.navigator as any).standalone || false,
      }));
    }

    mediaQuery.addEventListener('change', handleDisplayModeChange);
    return () => mediaQuery.removeEventListener('change', handleDisplayModeChange);
  }, []);

  return <ViewportContext.Provider value={state}>{children}</ViewportContext.Provider>;
}

// Hook to access the entire viewport state
export function useViewport() {
  const context = useContext(ViewportContext);
  if (context === undefined) {
    throw new Error('useViewport must be used within a ViewportProvider');
  }
  return context;
}

// Specialized hooks for specific viewport properties
export function useBreakpoint() {
  const context = useViewport();
  return context.breakpoint;
}

export function useDeviceType() {
  const context = useViewport();
  return context.deviceType;
}

export function useOrientation() {
  const context = useViewport();
  return context.orientation;
}

export function useViewportSize() {
  const context = useViewport();
  return { width: context.width, height: context.height };
}

export function useResponsiveValue<T>(values: Partial<Record<Breakpoint, T>>, defaultValue: T): T {
  const breakpoint = useBreakpoint();
  const breakpointOrder: Breakpoint[] = ['2xl', 'xl', 'lg', 'md', 'sm', 'xs'];

  // Find the closest defined breakpoint value
  const index = breakpointOrder.indexOf(breakpoint);
  for (let i = index; i < breakpointOrder.length; i++) {
    const value = values[breakpointOrder[i]];
    if (value !== undefined) {
      return value;
    }
  }

  return defaultValue;
}

import React, { createContext, useContext, useRef } from 'react';

type Selector<T, S> = (state: T) => S;

// Create a context with selectors support
export function createSelectableContext<T>(contextName: string) {
  const Context = createContext<T | undefined>(undefined);

  function Provider({ value, children }: { value: T; children: React.ReactNode }) {
    // Use a more straightforward approach without ref optimization for now
    return React.createElement(Context.Provider, { value }, children);
  }

  // Hook for selecting specific parts of the context state
  function useContextSelector<S>(selector: Selector<T, S>): S {
    const context = useContext(Context);
    if (context === undefined) {
      throw new Error(`use${contextName} must be used within a ${contextName}Provider`);
    }

    // For now, just return the selected value directly
    // TODO: Add memoization optimization later
    return selector(context);
  }

  // Hook for using the entire context
  function useEntireContext(): T {
    const context = useContext(Context);
    if (context === undefined) {
      throw new Error(`use${contextName} must be used within a ${contextName}Provider`);
    }
    return context;
  }

  return {
    Provider,
    useContextSelector,
    useEntireContext,
  };
}

