import { useState, useEffect, useCallback } from 'react';
import { useToast } from '../hooks/use-toast';

interface Progress {
  id?: number;
  timestamp: number;
  data: any;
}

interface OfflineState {
  isOnline: boolean;
  hasOfflineContent: boolean;
  pendingSyncs: number;
}

interface IDBStoreWithMethods extends IDBObjectStore {
  add(value: any): IDBRequest<IDBValidKey>;
  getAll(): IDBRequest<any[]>;
  clear(): IDBRequest<undefined>;
}

export function useOfflineSupport() {
  const [state, setState] = useState<OfflineState>({
    isOnline: navigator.onLine,
    hasOfflineContent: false,
    pendingSyncs: 0,
  });

  const { toast } = useToast();
  const addNotification = (message: string, type: 'success' | 'error' | 'info') => {
    toast({
      title: type === 'error' ? 'Error' : 'Notification',
      description: message,
      variant: type === 'error' ? 'destructive' : 'default',
    });
  };

  // Check if service worker is supported
  const isSupported = 'serviceWorker' in navigator;

  // Register service worker
  useEffect(() => {
    if (!isSupported) return;

    navigator.serviceWorker
      .register('/service-worker.js')
      .then((registration) => {
        console.log('ServiceWorker registration successful');

        // Check for background sync support
        if ('sync' in registration && typeof (registration as any).sync?.register === 'function') {
          (registration as any).sync
            .register('syncProgress')
            .then(() => console.log('Background sync registered'))
            .catch((err: Error) => console.error('Background sync registration failed:', err));
        }
      })
      .catch((error) => {
        console.error('ServiceWorker registration failed:', error);
      });
  }, [isSupported]);

  // Monitor online/offline status
  useEffect(() => {
    const handleOnline = () => {
      setState((prev) => ({ ...prev, isOnline: true }));
      addNotification('Back online! Syncing your progress...', 'success');
      syncOfflineProgress();
    };

    const handleOffline = () => {
      setState((prev) => ({ ...prev, isOnline: false }));
      addNotification('You are offline. Your progress will be saved locally.', 'info');
    };

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Track pending syncs
  const syncOfflineProgress = useCallback(async () => {
    if (!state.isOnline || !state.pendingSyncs) return;

    try {
      const db = await openDB();
      const transaction = db.transaction('progress', 'readwrite');
      const store = transaction.objectStore('progress') as IDBStoreWithMethods;

      // Get all pending progress items
      const pendingProgress = await new Promise<Progress[]>((resolve, reject) => {
        const request = store.getAll();
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      });

      // Sync each item
      for (const progress of pendingProgress) {
        try {
          // Here you would make your API call to sync the progress
          await fetch('/api/v1/progress/sync', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
            },
            body: JSON.stringify(progress),
          });
        } catch (error) {
          console.error('Failed to sync item:', error);
          continue;
        }
      }

      // Clear synced items
      await new Promise<void>((resolve, reject) => {
        const request = store.clear();
        request.onsuccess = () => resolve();
        request.onerror = () => reject(request.error);
      });

      setState((prev) => ({ ...prev, pendingSyncs: 0, hasOfflineContent: false }));
      addNotification('Progress synced successfully!', 'success');
    } catch (error) {
      console.error('Failed to sync progress:', error);
      addNotification('Failed to sync progress. Will try again later.', 'error');
    }
  }, [state.isOnline, state.pendingSyncs]);

  // Save progress locally when offline
  const saveOfflineProgress = useCallback(async (data: any) => {
    try {
      const db = await openDB();
      const transaction = db.transaction('progress', 'readwrite');
      const store = transaction.objectStore('progress') as IDBStoreWithMethods;

      const progress: Progress = {
        timestamp: Date.now(),
        data,
      };

      await new Promise<IDBValidKey>((resolve, reject) => {
        const request = store.add(progress);
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      });

      setState((prev) => ({
        ...prev,
        pendingSyncs: prev.pendingSyncs + 1,
        hasOfflineContent: true,
      }));
      addNotification('Progress saved offline', 'info');
    } catch (error) {
      console.error('Failed to save progress:', error);
      addNotification('Failed to save progress offline', 'error');
    }
  }, []);

  return {
    isOnline: state.isOnline,
    hasOfflineContent: state.hasOfflineContent,
    pendingSyncs: state.pendingSyncs,
    isSupported,
    saveOfflineProgress,
    syncOfflineProgress,
  };
}

// Helper function to open IndexedDB
function openDB(): Promise<IDBDatabase> {
  return new Promise<IDBDatabase>((resolve, reject) => {
    const request = indexedDB.open('sambhidanx-offline', 1);

    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result);

    request.onupgradeneeded = (event: IDBVersionChangeEvent) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains('progress')) {
        db.createObjectStore('progress', { keyPath: 'id', autoIncrement: true });
      }
    };
  });
}

import React, { useMemo, useCallback, useRef, useEffect, useState } from 'react';

// Generic memoization hook for expensive operations
export function useMemoizedValue<T>(value: T, deps: React.DependencyList): T {
  return useMemo(() => value, deps);
}

// Debounce hook for rate-limiting state updates
export function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState(value);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(handler);
    };
  }, [value, delay]);

  return debouncedValue;
}

// Debounce hook for functions
export function useDebouncedCallback<T extends (...args: any[]) => any>(
  callback: T,
  delay: number
): T {
  const timeoutRef = useRef<ReturnType<typeof setTimeout>>();

  return useCallback(
    (...args: Parameters<T>) => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }

      timeoutRef.current = setTimeout(() => {
        callback(...args);
      }, delay);
    },
    [callback, delay]
  ) as T;
}

// Throttle hook for limiting the rate of function calls
export function useThrottle<T extends (...args: any[]) => any>(func: T, delay: number): T {
  const lastRan = useRef(Date.now());

  return useCallback(
    (...args: Parameters<T>) => {
      const now = Date.now();

      if (now - lastRan.current >= delay) {
        func(...args);
        lastRan.current = now;
      }
    },
    [func, delay]
  ) as T;
}

// Hook for tracking expensive renders and logging performance issues
export function useRenderTracking(componentName: string) {
  const renderCount = useRef(0);
  const lastRenderTime = useRef(performance.now());

  useEffect(() => {
    const currentTime = performance.now();
    const timeSinceLastRender = currentTime - lastRenderTime.current;
    renderCount.current += 1;

    if (timeSinceLastRender > 16) {
      // More than 1 frame (60fps)
      console.warn(
        `Slow render detected in ${componentName}:`,
        `Render #${renderCount.current} took ${timeSinceLastRender.toFixed(2)}ms`
      );
    }

    lastRenderTime.current = currentTime;
  });
}

// Hook for detecting unnecessary re-renders
export function useRenderOptimization(componentName: string, props: Record<string, any>) {
  const prevProps = useRef<Record<string, any>>({});

  useEffect(() => {
    const changedProps: Record<string, { prev: any; next: any }> = {};

    Object.entries(props).forEach(([key, value]) => {
      if (prevProps.current[key] !== value) {
        changedProps[key] = {
          prev: prevProps.current[key],
          next: value,
        };
      }
    });

    if (Object.keys(changedProps).length > 0) {
      console.log(`${componentName} re-rendered due to prop changes:`, changedProps);
    }

    prevProps.current = props;
  });
}

// Hook for caching expensive calculations
export function useCalculationCache<T>(calculation: () => T, deps: any[], cacheSize: number = 10) {
  const cache = useRef<Map<string, T>>(new Map());

  return useMemo(() => {
    const key = JSON.stringify(deps);
    if (cache.current.has(key)) {
      return cache.current.get(key)!;
    }

    const result = calculation();

    // Implement LRU cache
    if (cache.current.size >= cacheSize) {
      const iteratorResult = cache.current.keys().next();
      if (!iteratorResult.done) {
        cache.current.delete(iteratorResult.value as string);
      }
    }

    cache.current.set(key, result);
    return result;
  }, deps);
}

// Hook for detecting context consumers and measuring context usage
export function useContextMetrics(contextName: string) {
  useEffect(() => {
    const metric = {
      contextName,
      timestamp: Date.now(),
      componentPath: new Error().stack
        ?.split('\n')[2]
        ?.trim()
        ?.replace(/^at\s+/, ''),
    };

    // You could send this to your analytics or monitoring service
    if (process.env.NODE_ENV === 'development') {
      console.log('Context usage metric:', metric);
    }
  }, [contextName]);
}

import * as React from 'react';

import type { ToastActionElement, ToastProps } from '@/components/ui/toast';

const TOAST_LIMIT = 1;
const TOAST_REMOVE_DELAY = 1000000;

type ToasterToast = ToastProps & {
  id: string;
  title?: React.ReactNode;
  description?: React.ReactNode;
  action?: ToastActionElement;
};

const actionTypes = {
  ADD_TOAST: 'ADD_TOAST',
  UPDATE_TOAST: 'UPDATE_TOAST',
  DISMISS_TOAST: 'DISMISS_TOAST',
  REMOVE_TOAST: 'REMOVE_TOAST',
} as const;

let count = 0;

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER;
  return count.toString();
}

type ActionType = typeof actionTypes;

type Action =
  | {
      type: ActionType['ADD_TOAST'];
      toast: ToasterToast;
    }
  | {
      type: ActionType['UPDATE_TOAST'];
      toast: Partial<ToasterToast>;
    }
  | {
      type: ActionType['DISMISS_TOAST'];
      toastId?: ToasterToast['id'];
    }
  | {
      type: ActionType['REMOVE_TOAST'];
      toastId?: ToasterToast['id'];
    };

interface State {
  toasts: ToasterToast[];
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>();

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return;
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId);
    dispatch({
      type: 'REMOVE_TOAST',
      toastId: toastId,
    });
  }, TOAST_REMOVE_DELAY);

  toastTimeouts.set(toastId, timeout);
};

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case 'ADD_TOAST':
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      };

    case 'UPDATE_TOAST':
      return {
        ...state,
        toasts: state.toasts.map((t) => (t.id === action.toast.id ? { ...t, ...action.toast } : t)),
      };

    case 'DISMISS_TOAST': {
      const { toastId } = action;

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId);
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id);
        });
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t
        ),
      };
    }
    case 'REMOVE_TOAST':
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        };
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      };
  }
};

const listeners: Array<(state: State) => void> = [];

let memoryState: State = { toasts: [] };

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action);
  listeners.forEach((listener) => {
    listener(memoryState);
  });
}

type Toast = Omit<ToasterToast, 'id'>;

function toast({ ...props }: Toast) {
  const id = genId();

  const update = (props: ToasterToast) =>
    dispatch({
      type: 'UPDATE_TOAST',
      toast: { ...props, id },
    });
  const dismiss = () => dispatch({ type: 'DISMISS_TOAST', toastId: id });

  dispatch({
    type: 'ADD_TOAST',
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss();
      },
    },
  });

  return {
    id: id,
    dismiss,
    update,
  };
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState);

  React.useEffect(() => {
    listeners.push(setState);
    return () => {
      const index = listeners.indexOf(setState);
      if (index > -1) {
        listeners.splice(index, 1);
      }
    };
  }, [state]);

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: 'DISMISS_TOAST', toastId }),
  };
}

export { useToast, toast };

import { locales } from './locales';

export type SupportedLanguage = keyof typeof locales; // 'en' | 'ne'

export interface TranslatorOptions {
  fallback?: SupportedLanguage;
}

type LocaleRecord = (typeof locales)[SupportedLanguage];
type TranslationKey = keyof typeof locales.en & string; // keys shared across locales

export async function createTranslator(lang: SupportedLanguage, opts: TranslatorOptions = {}) {
  const fallbackLang = opts.fallback || 'en';
  const primary = locales[lang];
  const fallback = lang === fallbackLang ? primary : locales[fallbackLang];
  return (key: string) => {
    // If key is a known translation key, return value; else return key itself.
    if ((primary as Record<string, string>)[key] !== undefined) {
      return (primary as Record<string, string>)[key];
    }
    if ((fallback as Record<string, string>)[key] !== undefined) {
      return (fallback as Record<string, string>)[key];
    }
    return key;
  };
}

