// API client for progress tracking endpoints

const API_BASE = '/api/v1';

export interface LessonProgressRequest {
  lessonId: string;
  userId: string;
  completed?: boolean;
}

export interface QuizResultRequest {
  quizId: string;
  userId: string;
  score: number;
  totalQuestions: number;
  correctAnswers: number;
}

export interface ProgressResponse {
  status: string;
  message?: string;
  progress?: any;
  result?: any;
}

export interface UserProgressData {
  completedLessons: string[];
  quizResults: { id: string; score: number; totalQuestions: number }[];
  achievements: string[];
}

class ProgressAPI {
  private async request<T>(endpoint: string, options?: RequestInit): Promise<T> {
    const url = `${API_BASE}${endpoint}`;

    try {
      const response = await fetch(url, {
        headers: {
          'Content-Type': 'application/json',
          ...options?.headers,
        },
        credentials: 'same-origin',
        ...options,
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(
          `API request failed: ${response.status} ${response.statusText}. Response: ${errorText}`
        );
      }

      const data = await response.json();
      return data;
    } catch (error) {
      if (error instanceof TypeError && error.message.includes('fetch')) {
        throw new Error(
          'Network error: Unable to connect to server. Please check if the server is running.'
        );
      }
      throw error;
    }
  }

  async markLessonComplete(data: LessonProgressRequest): Promise<ProgressResponse> {
    return this.request<ProgressResponse>('/progress/lesson', {
      method: 'POST',
      body: JSON.stringify(data),
    });
  }

  async recordQuizResult(data: QuizResultRequest): Promise<ProgressResponse> {
    return this.request<ProgressResponse>('/progress/quiz', {
      method: 'POST',
      body: JSON.stringify(data),
    });
  }

  async getUserProgress(userId: string): Promise<{ status: string; data: UserProgressData }> {
    return this.request<{ status: string; data: UserProgressData }>(`/progress/${userId}`);
  }

  // Utility to generate a temporary user ID for demo purposes
  getUserId(): string {
    let userId = localStorage.getItem('demo-user-id');
    if (!userId) {
      userId = `demo-user-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
      localStorage.setItem('demo-user-id', userId);
    }
    return userId;
  }
}

export const progressAPI = new ProgressAPI();

// Browser console logger that sends logs to server for debugging
let originalConsole: any = {};

// Store original console methods
['log', 'error', 'warn', 'info'].forEach((method) => {
  originalConsole[method] = console[method as keyof Console];
});

// Function to send logs to server
async function sendLogToServer(level: string, message: string, error?: any) {
  try {
    await fetch('/api/v1/log', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        level,
        message: typeof message === 'string' ? message : JSON.stringify(message),
        error: error ? error.stack || error.toString() : undefined,
        url: window.location.href,
        timestamp: new Date().toISOString(),
      }),
    });
  } catch (e) {
    // Silently fail if server logging fails
  }
}

// Override console methods to also log to server
export function enableServerLogging() {
  console.log = (...args: any[]) => {
    originalConsole.log.apply(console, args);
    sendLogToServer('log', args.join(' '));
  };

  console.error = (...args: any[]) => {
    originalConsole.error.apply(console, args);
    sendLogToServer('error', args.join(' '), args[0]);
  };

  console.warn = (...args: any[]) => {
    originalConsole.warn.apply(console, args);
    sendLogToServer('warn', args.join(' '));
  };

  console.info = (...args: any[]) => {
    originalConsole.info.apply(console, args);
    sendLogToServer('info', args.join(' '));
  };

  // Capture unhandled errors
  window.addEventListener('error', (event) => {
    sendLogToServer('error', 'Unhandled Error: ' + event.message, {
      filename: event.filename,
      lineno: event.lineno,
      colno: event.colno,
      error: event.error?.stack || event.error?.toString(),
    });
  });

  // Capture unhandled promise rejections
  window.addEventListener('unhandledrejection', (event) => {
    sendLogToServer('error', 'Unhandled Promise Rejection: ' + event.reason, {
      reason: event.reason?.stack || event.reason?.toString(),
    });
  });

  console.log('🔍 Server logging enabled - browser console will be mirrored to server terminal');
}

// Restore original console methods
export function disableServerLogging() {
  Object.keys(originalConsole).forEach((method) => {
    (console as any)[method] = originalConsole[method];
  });
}

import { createRoot } from 'react-dom/client';
import { ErrorProvider } from './contexts/ErrorContext';
import { AppStateProvider } from './contexts/AppStateContext';
import { Toaster } from './components/ui/toaster';
import { AuthProvider, useAuth } from './contexts/AuthContext';
import { ViewportProvider } from './contexts/ViewportContext';
import { LanguageProvider } from './contexts/LanguageContext';
import { LearningProvider } from './contexts/LearningContext';
import { BookmarksProvider } from './contexts/BookmarksContext';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { enableServerLogging } from './lib/serverLogger';
import App from './App';
import './index.css';

// Development-only helpers
if (import.meta.env.DEV) {
  enableServerLogging();

  // In development, an aggressive service worker cache previously captured
  // Vite virtual modules like /@react-refresh leading to stale runtime code
  // (missing named exports) and the error: "The requested module '/@react-refresh' does not provide an export named 'injectIntoGlobalHook'".
  // To avoid ALL SW interference with Vite HMR, we fully unregister any
  // existing service workers and clear related caches during dev.
  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.getRegistrations().then((regs) => {
      for (const reg of regs) {
        reg.unregister().catch(() => {
          /* ignore */
        });
      }
    });
    if ('caches' in window) {
      caches.keys().then((keys) => {
        for (const k of keys) {
          if (k.startsWith('sambhidanx-')) {
            caches.delete(k).catch(() => {
              /* ignore */
            });
          }
        }
      });
    }
  }
}

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 5 * 60 * 1000, // 5 minutes
      gcTime: 30 * 60 * 1000, // 30 minutes (was cacheTime in v4)
      retry: 1,
      refetchOnWindowFocus: false,
    },
  },
});

function AuthenticatedApp() {
  const { user } = useAuth();
  return (
    <LearningProvider userId={user?.id}>
      <BookmarksProvider>
        <App />
      </BookmarksProvider>
    </LearningProvider>
  );
}

createRoot(document.getElementById('root')!).render(
  <ErrorProvider>
    <QueryClientProvider client={queryClient}>
      <ViewportProvider>
        <LanguageProvider>
          <AuthProvider>
            <AppStateProvider>
              <AuthenticatedApp />
              <Toaster />
            </AppStateProvider>
          </AuthProvider>
        </LanguageProvider>
      </ViewportProvider>
    </QueryClientProvider>
  </ErrorProvider>
);

// Register service worker ONLY in production to prevent dev caching issues.
if (!import.meta.env.DEV && 'serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    const versionParam = `v=${Date.now()}`; // force fresh fetch
    navigator.serviceWorker
      .register(`/service-worker.js?${versionParam}`)
      .then((registration) => {
        console.log('ServiceWorker new registration scope:', registration.scope);
      })
      .catch((error) => {
        console.error('ServiceWorker registration failed:', error);
      });
  });

  navigator.serviceWorker.addEventListener('message', (event) => {
    if (event.data?.type === 'SW_ACTIVATED') {
      console.log('[SW] Activated version', event.data.version);
      if (!sessionStorage.getItem('sw-reloaded')) {
        sessionStorage.setItem('sw-reloaded', '1');
        window.location.reload();
      }
    }
  });
}

