app.use((req, res, next) => {
  const start = Date.now();
  const path = req.path;
  let capturedJsonResponse: Record<string, any> | undefined = undefined;

  const originalResJson = res.json;
  res.json = function (bodyJson, ...args) {
    capturedJsonResponse = bodyJson;
    return originalResJson.apply(res, [bodyJson, ...args]);
  };

  res.on('finish', () => {
    const duration = Date.now() - start;
    if (path.startsWith('/api')) {
      let logLine = `${req.method} ${path} ${res.statusCode} in ${duration}ms`;
      if (capturedJsonResponse) {
        logLine += ` :: ${JSON.stringify(capturedJsonResponse)}`;
      }

      if (logLine.length > 80) {
        logLine = logLine.slice(0, 79) + '…';
      }

      log(logLine);
    }
  });

  next();
});

import net from 'net';

async function findAvailablePort(start: number, maxAttempts = 10): Promise<number> {
  for (let i = 0; i < maxAttempts; i++) {
    const port = start + i;
    const available = await new Promise<boolean>((resolve) => {
      const tester = net
        .createServer()
        .once('error', () => resolve(false))
        .once('listening', () => tester.close(() => resolve(true)))
        .listen(port, '0.0.0.0');
    });
    if (available) return port;
  }
  throw new Error(`No available port found starting from ${start}`);
}

(async () => {
  // Always start from port 5001 to avoid conflicts with other services
  const resolvedPort = await findAvailablePort(5001);
  if (resolvedPort !== 5001) {
    log(`port 5001 in use, switching to ${resolvedPort}`);
  }
  // Override config.port locally (do not mutate config object if frozen externally)
  const effectivePort = resolvedPort;

  const server = await registerRoutes(app);

  // Global error handling middleware
  app.use(errorHandler);

  // importantly only setup vite in development and after
  // setting up all the other routes so the catch-all route
  // doesn't interfere with the other routes
  if (app.get('env') === 'development') {
    await setupVite(app, server);
  } else {
    serveStatic(app);
  }

  // ALWAYS serve the app on the port specified in the environment variable PORT
  // Other ports are firewalled. Default to 5000 if not specified.
  // this serves both the API and the client.
  // It is the only port that is not firewalled.
  server.listen(
    {
      port: effectivePort,
      host: '0.0.0.0',
      reusePort: true,
    },
    () => {
      log(`serving on port ${effectivePort}`);
    }
  );
})();

import { Request, Response, NextFunction } from 'express';

interface ErrorResponse {
  status: string;
  message: string;
  stack?: string;
  errors?: any[];
}

export const errorHandler = (err: any, req: Request, res: Response, next: NextFunction) => {
  const error: ErrorResponse = {
    status: 'error',
    message: err.message || 'Internal Server Error',
  };

  // Add stack trace in development
  if (process.env.NODE_ENV === 'development') {
    error.stack = err.stack;
  }

  // Handle specific error types
  if (err.name === 'ValidationError') {
    error.message = 'Validation Error';
    error.errors = Object.values(err.errors).map((err: any) => err.message);
    res.status(400);
  } else if (err.name === 'UnauthorizedError') {
    error.message = 'Unauthorized Access';
    res.status(401);
  } else {
    res.status(err.status || 500);
  }

  res.json(error);
};

import contactRoute from './contactRoute';
import type { Express } from 'express';
import express from 'express';
import { z } from 'zod';
import { createServer, type Server } from 'http';
import { storage } from './storage';

export async function registerRoutes(app: Express): Promise<Server> {
  const API_VERSION = 'v1';

  // Health check endpoint
  app.get('/health', (req, res) => {
    res.status(200).json({ status: 'healthy', timestamp: new Date().toISOString() });
  });

  // API routes with versioning
  app.use(`/api/${API_VERSION}`, contactRoute);

  // Unified progress sync endpoint (keeping existing one)
  const progressSchema = z.object({
    progress: z
      .array(
        z.object({
          lessonId: z.string(),
          sectionId: z.string().optional(),
          completed: z.boolean().optional(),
          points: z.number().optional(),
          timestamp: z.string().optional(),
        })
      )
      .min(1),
  });

  app.post(`/api/${API_VERSION}/progress/sync`, express.json(), (req, res) => {
    const parse = progressSchema.safeParse(req.body);
    if (!parse.success) {
      return res.status(400).json({ error: 'Invalid payload', issues: parse.error.issues });
    }
    // TODO: Persist progress to storage (stub)
    res.status(200).json({ status: 'ok', received: parse.data.progress.length });
  });

  // use storage to perform CRUD operations on the storage interface
  // e.g. storage.insertUser(user) or storage.getUserByUsername(username)

  const httpServer = createServer(app);

  return httpServer;
}

import { eq, and } from 'drizzle-orm';
import { db } from './db';
import { users, userProgress, quizResults, userAchievements, bookmarks } from './db/schema';
import { randomUUID } from 'crypto';

export interface IStorage {
  // User methods
  getUser(id: string): Promise<any>;
  getUserByUsername(username: string): Promise<any>;
  createUser(user: { username: string; password: string }): Promise<any>;

  // Progress methods
  getUserProgress(userId: string, lessonId: string): Promise<any>;
  updateUserProgress(userId: string, lessonId: string, progress: number): Promise<any>;
  markLessonComplete(userId: string, lessonId: string): Promise<any>;

  // Quiz methods
  saveQuizResult(
    userId: string,
    quizId: string,
    score: number,
    totalQuestions: number,
    correctAnswers: number
  ): Promise<any>;
  getQuizResults(userId: string, quizId: string): Promise<any>;

  // Achievement methods
  unlockAchievement(userId: string, achievementId: string): Promise<any>;
  getUserAchievements(userId: string): Promise<any>;

  // Bookmark methods
  addBookmark(userId: string, lessonId: string): Promise<any>;
  removeBookmark(userId: string, lessonId: string): Promise<any>;
  getBookmarks(userId: string): Promise<any>;
}

export class SqliteStorage implements IStorage {
  async getUser(id: string) {
    return await db.select().from(users).where(eq(users.id, id)).get();
  }

  async getUserByUsername(username: string) {
    return await db.select().from(users).where(eq(users.username, username)).get();
  }

  async createUser(userData: { username: string; password: string }) {
    const id = randomUUID();
    await db.insert(users).values({ ...userData, id });
    return this.getUser(id);
  }

  async getUserProgress(userId: string, lessonId: string) {
    return await db
      .select()
      .from(userProgress)
      .where(and(eq(userProgress.userId, userId), eq(userProgress.lessonId, lessonId)))
      .get();
  }

  async updateUserProgress(userId: string, lessonId: string, progress: number) {
    const existing = await this.getUserProgress(userId, lessonId);
    const id = existing?.id || randomUUID();

    if (existing) {
      await db.update(userProgress).set({ progress }).where(eq(userProgress.id, id));
    } else {
      await db.insert(userProgress).values({ id, userId, lessonId, progress });
    }

    return this.getUserProgress(userId, lessonId);
  }

  async markLessonComplete(userId: string, lessonId: string) {
    const existing = await this.getUserProgress(userId, lessonId);
    const id = existing?.id || randomUUID();

    if (existing) {
      await db
        .update(userProgress)
        .set({ progress: 100, completed: true })
        .where(eq(userProgress.id, id));
    } else {
      await db
        .insert(userProgress)
        .values({ id, userId, lessonId, progress: 100, completed: true });
    }

    return this.getUserProgress(userId, lessonId);
  }

  async saveQuizResult(
    userId: string,
    quizId: string,
    score: number,
    totalQuestions: number,
    correctAnswers: number
  ) {
    const id = randomUUID();
    await db.insert(quizResults).values({
      id,
      userId,
      quizId,
      score,
      totalQuestions,
      correctAnswers,
    });
    return this.getQuizResults(userId, quizId);
  }

  async getQuizResults(userId: string, quizId: string) {
    return await db
      .select()
      .from(quizResults)
      .where(and(eq(quizResults.userId, userId), eq(quizResults.quizId, quizId)))
      .all();
  }

  async unlockAchievement(userId: string, achievementId: string) {
    // Check if achievement already exists
    const existing = await db
      .select()
      .from(userAchievements)
      .where(
        and(eq(userAchievements.userId, userId), eq(userAchievements.achievementId, achievementId))
      )
      .get();

    if (!existing) {
      const id = randomUUID();
      await db.insert(userAchievements).values({ id, userId, achievementId });
    }

    return this.getUserAchievements(userId);
  }

  async getUserAchievements(userId: string) {
    return await db
      .select()
      .from(userAchievements)
      .where(eq(userAchievements.userId, userId))
      .all();
  }

  async addBookmark(userId: string, lessonId: string) {
    // Check if bookmark already exists
    const existing = await db
      .select()
      .from(bookmarks)
      .where(and(eq(bookmarks.userId, userId), eq(bookmarks.lessonId, lessonId)))
      .get();

    if (!existing) {
      const id = randomUUID();
      await db.insert(bookmarks).values({ id, userId, lessonId });
    }

    return this.getBookmarks(userId);
  }

  async removeBookmark(userId: string, lessonId: string) {
    await db
      .delete(bookmarks)
      .where(and(eq(bookmarks.userId, userId), eq(bookmarks.lessonId, lessonId)));
  }

  async getBookmarks(userId: string) {
    return await db.select().from(bookmarks).where(eq(bookmarks.userId, userId)).all();
  }
}

export const storage = new SqliteStorage();

import { promises as fs } from 'fs';
import path from 'path';
import {
  ContentManifestSchema,
  LessonContentSchema,
  QuizContentSchema,
  type ContentManifest,
  type LessonContent,
  type QuizContent,
} from './contentSchemas';

// Simple in-memory caches. In production with multiple processes you'd swap for a shared cache.
const manifestCache: { value?: ContentManifest; mtimeMs?: number } = {};
const lessonCache = new Map<string, LessonContent>();
const quizCache = new Map<string, QuizContent>();

const CONTENT_ROOT = path.resolve(process.cwd(), 'content');

async function readJSON<T>(filePath: string): Promise<T> {
  const raw = await fs.readFile(filePath, 'utf-8');
  return JSON.parse(raw) as T;
}

export async function loadManifest(force = false): Promise<ContentManifest> {
  const manifestPath = path.join(CONTENT_ROOT, 'manifest.json');
  const stat = await fs.stat(manifestPath);
  if (!force && manifestCache.value && manifestCache.mtimeMs === stat.mtimeMs) {
    return manifestCache.value;
  }
  const json = await readJSON<any>(manifestPath);
  const parsed = ContentManifestSchema.parse(json);
  manifestCache.value = parsed;
  manifestCache.mtimeMs = stat.mtimeMs;
  return parsed;
}

export async function listLessons(): Promise<
  Pick<LessonContent, 'id' | 'title' | 'difficulty' | 'estimatedTime' | 'icon'>[]
> {
  const manifest = await loadManifest();
  return manifest.lessons.map((l) => ({
    id: l.id,
    title: l.title,
    difficulty: l.difficulty,
    estimatedTime: l.estimatedTime,
    icon: l.icon,
  }));
}

export async function listQuizzes(): Promise<Pick<QuizContent, 'id' | 'title' | 'category'>[]> {
  const manifest = await loadManifest();
  return manifest.quizzes.map((q) => ({ id: q.id, title: q.title, category: q.category }));
}

export async function loadLesson(id: string, force = false): Promise<LessonContent> {
  if (!force && lessonCache.has(id)) return lessonCache.get(id)!;
  const manifest = await loadManifest();
  const entry = manifest.lessons.find((l) => l.id === id);
  if (!entry) throw new Error(`Lesson not found: ${id}`);
  const lessonPath = path.join(CONTENT_ROOT, entry.file);
  const json = await readJSON<any>(lessonPath);
  const parsed = LessonContentSchema.parse(json);
  lessonCache.set(id, parsed);
  return parsed;
}

export async function loadQuiz(id: string, force = false): Promise<QuizContent> {
  if (!force && quizCache.has(id)) return quizCache.get(id)!;
  const manifest = await loadManifest();
  const entry = manifest.quizzes.find((q) => q.id === id);
  if (!entry) throw new Error(`Quiz not found: ${id}`);
  const quizPath = path.join(CONTENT_ROOT, entry.file);
  const json = await readJSON<any>(quizPath);
  const parsed = QuizContentSchema.parse(json);
  quizCache.set(id, parsed);
  return parsed;
}

export function clearContentCache() {
  manifestCache.value = undefined;
  manifestCache.mtimeMs = undefined;
  lessonCache.clear();
  quizCache.clear();
}

// Utility to preload all content (e.g., warmup during server start if desired)
export async function preloadAllContent(): Promise<{ lessons: number; quizzes: number }> {
  const manifest = await loadManifest();
  await Promise.all(manifest.lessons.map((l) => loadLesson(l.id)));
  await Promise.all(manifest.quizzes.map((q) => loadQuiz(q.id)));
  return { lessons: manifest.lessons.length, quizzes: manifest.quizzes.length };
}

